--
-- Структура таблицы `events`
--

CREATE TABLE IF NOT EXISTS `events` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Название мероприятия',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Категория: МЕРОПРИЯТИЯ, АКЦИИ, ФЕСТИВАЛИ, ЛЕКЦИИ, КОНКУРСЫ',
  `date` date NOT NULL COMMENT 'Дата проведения (YYYY-MM-DD)',
  `location` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Место проведения',
  `time` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Время проведения',
  `entry` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Вход: платный/бесплатный/сумма',
  `short_description` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Краткое описание (для карусели)',
  `full_description` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Полное описание',
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ссылка на фото мероприятия',
  `link` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '#' COMMENT 'Ссылка для подробностей (если есть)',
  `is_active` tinyint(1) DEFAULT '1' COMMENT 'Активно ли мероприятие (1=да, 0=нет)',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_date` (`date`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `events`
--

INSERT INTO `events` (`id`, `title`, `category`, `date`, `location`, `time`, `entry`, `short_description`, `full_description`, `image_url`, `link`, `is_active`, `created_at`) VALUES
(1, 'Зелёный Марафон от Сбербанка', 'МЕРОПРИЯТИЯ', '2026-06-05', 'Спорт Порт стадиона «Нижний Новгород»', 'Начало регистрации в 8:00, торжественное открытие в 10:00', 'Платный (регистрационный взнос)', 'Зелёный Марафон — традиционный спортивный праздник от Сбера, объединяющий тысячи любителей бега.', 'Зелёный Марафон — это традиционный спортивный праздник от Сбера... (полное описание)', 'img\\зелен.jpg', '/event/zeleniy-marafon', 1, '2026-04-21 15:33:43'),
(2, 'Благотворительный полумарафон «Беги, герой!»', 'МЕРОПРИЯТИЯ', '2026-05-23', 'Стадион «Совкомбанк Арена»', '23 мая: детские старты, 24 мая: 10 км и 21,1 км', '2800–3400 руб.', 'Самый массовый любительский забег Нижегородской области.', '«Беги, герой!» — это самый массовый любительский забег... (полное описание)', 'img\\беги.jpg', '/event/begi-geroy', 1, '2026-04-21 15:33:43'),
(3, 'Всероссийская акция «БумБатл»', 'АКЦИИ', '2026-11-15', 'Вся Нижегородская область', 'Акция уже идет!', 'Бесплатный', 'Соревнование по сбору макулатуры.', 'Хотите спасти деревья и выиграть призы? Участвуйте в «БумБатле»!... (полное описание)', 'img\\бумбатл.jpg', '/event/bum-battle', 1, '2026-04-21 15:33:43'),
(4, 'Фестиваль BOTANICA 2026', 'ФЕСТИВАЛИ', '2026-07-11', 'Александровский сад, Нижний Новгород', 'Весь день', 'Вход свободный', 'Ежегодный семейный фестиваль о любви к природе и искусству.', 'BOTANICA — это ежегодный семейный фестиваль о любви к природе и искусству... (полное описание)', 'img\\ботаника.png', '/event/botanica', 1, '2026-04-21 15:33:43'),
(5, 'X Международный экологический телефестиваль «Территория завтра»', 'ФЕСТИВАЛИ', '2026-09-02', 'Центр экологического просвещения «Экоториум» (парк «Швейцария») и другие площадки города', '10:00–20:00 (основные дни)', 'Бесплатный', 'Юбилейный фестиваль экологического кино и журналистики.', 'X Международный экологический телефестиваль «Территория завтра» — это юбилейный смотр лучших фильмов, телерепортажей и мультимедийных проектов, посвящённых охране окружающей среды. В конкурсной программе участвуют журналисты, режиссёры и блогеры из разных стран, чьи работы поднимают вопросы изменения климата, сохранения биоразнообразия и экологического просвещения. Гостей фестиваля ждут не только кинопоказы, но и творческие встречи с авторами, лекции экспертов, а также мастер-классы по созданию экоконтента. Фестиваль в десятый раз станет площадкой для диалога между экоактивистами, медийщиками и всеми, кому небезразлично будущее нашей планеты.Конкурс фильмов, мультфильмов и репортажей на тему экологии, мастер-классы, показы и обсуждения. Нижний Новгород в десятый раз становится центром «зелёной» документалистики.', 'img/Территория.jpg', 'https://xn----8sbahmnfa7csacfqeh0t.xn--p1ai/', 1, '2026-04-22 11:13:39'),
(6, 'Экофестиваль «АртЛуга» (заповедная земля)', 'ФЕСТИВАЛИ', '2026-08-07', 'Берег Волги, зона отдыха Щелоковский хутор', '11:00–22:00', 'Бесплатный', 'Семейный фестиваль экологии, йоги и творчества на природе.', 'Экофестиваль «АртЛуга» (заповедная земля) — это семейный праздник на природе, где экология встречается с творчеством, йогой и здоровым образом жизни. Гостей ждут лекции об осознанном потреблении, мастер-классы по созданию арт-объектов из природных материалов, йога-практики на закате у воды и выступления этнографических коллективов. На фестивале также работает фермерский маркет с органической едой, зона буккроссинга и детская площадка с экоиграми. «АртЛуга» доказывает, что забота о планете может быть вдохновляющей, красивой и душевной.', 'img/АртЛуга.png', 'https://vk.com/artluga.fest', 1, '2026-04-22 11:13:39'),
(7, 'Всемирный день окружающей среды — «Зелёный Нижний»', 'АКЦИИ', '2026-06-05', 'Парк «Швейцария» и набережная Волги', '12:00–18:00', 'Бесплатный', 'Масштабная акция по посадке деревьев и просвещению.', 'Всемирный день окружающей среды — «Зелёный Нижний» — это масштабный городской праздник, посвящённый заботе о планете и озеленению любимого города. В программе дня: массовая посадка деревьев и кустарников в парках и на набережных, велопарад в поддержку чистого воздуха, эколекции от приглашённых экспертов, конкурсы экологических плакатов и «зелёные» концерты местных музыкальных групп. Каждый желающий сможет внести личный вклад в улучшение экологии: посадить своё дерево, сдать вторсырьё или просто узнать, как сделать повседневную жизнь более осознанной. «Зелёный Нижний» доказывает, что бережное отношение к природе начинается с простых действий, которые объединяют тысячи неравнодушных жителей.', 'img/ЗеленНиж.jpg', 'https://admgor.nnov.ru', 1, '2026-04-22 11:13:39'),
(8, 'Всероссийский экологический субботник «Чистый Нижний»', 'АКЦИИ', '2026-04-25', 'Все районы города (центральные парки, набережные)', '09:00–13:00', 'Бесплатный', 'Городская уборка территорий.', 'Всероссийский экологический субботник «Чистый Нижний» — это ежегодная акция, объединяющая жителей города для совместной уборки парков, скверов, набережных и берегов рек. Тысячи волонтёров с мусорными мешками и перчатками выходят на улицы, чтобы сделать любимый город чище, а заодно принять участие в интерактивных экологических играх и конкурсах для детей и взрослых. Субботник не только помогает навести порядок в общественных пространствах, но и формирует культуру ответственного отношения к природе, показывая, что чистота начинается с каждого из нас.', 'img/Субботник.jpg', 'https://niann.ru', 1, '2026-04-22 11:13:39'),
(9, 'Фестиваль экологических агитбригад «Наш дом — Нижний Новгород»', 'ФЕСТИВАЛИ', '2026-12-05', 'Дом народного единства', '11:00–16:00', 'Бесплатный', 'Творческий конкурс школьных и студенческих агитбригад.', 'Фестиваль экологических агитбригад «Наш дом — Нижний Новгород» — это творческий конкурс, в котором школьные и студенческие команды представляют театрализованные номера, сценки, стихи и песни на тему защиты окружающей среды. Юные экологи в ярких костюмах с плакатами и реквизитом доносят до зрителей важные идеи о раздельном сборе мусора, экономии воды, сохранении лесов и бережном отношении к животным. Жюри оценивает артистизм, оригинальность и экологическую грамотность выступлений, а лучшие агитбригады получают дипломы и призы. Фестиваль не только дарит заряд энергии и позитива, но и воспитывает в молодёжи активную гражданскую позицию — ведь заботиться о природе нужно не в одиночку, а всем домом, всем городом.', 'img/НашДом.jpg', 'https://xn----8sbfgbfw2ane3bm.xn--p1ai', 1, '2026-04-22 11:13:39'),
(11, 'День Земли — «Планета в наших руках»', 'АКЦИИ', '2026-04-22', 'Александровский сад и Кремль', '11:00–17:00', 'Бесплатный', 'Праздник в честь Дня Земли.', 'День Земли — «Планета в наших руках» — это ежегодный городской праздник, посвящённый нашему общему дому и призванный напомнить каждому о хрупкости природы и важности бережного к ней отношения. В программе мероприятия: яркие флешмобы с зелёными шарами и костюмами, познавательные мастер-классы по раздельному сбору отходов и правильному обращению с опасными отходами (батарейками, лампами), а также выставка детских рисунков на экологическую тему. Все желающие смогут принять участие в акции по сбору использованных батареек и узнать, как маленькие шаги каждого помогают спасти планету для будущих поколений.', 'img/ДеньЗемли.jpg', 'https://eco-project.org', 1, '2026-04-22 11:13:39'),
(12, 'Акция «Чистые берега Волги»', 'АКЦИИ', '2026-09-15', 'Набережная Волги (от Кремля до Канавина)', '10:00–14:00', 'Бесплатный', 'Уборка прибрежной зоны.', 'Акция «Чистые берега Волги» — это ежегодный волонтёрский проект, направленный на очистку прибрежной зоны главной водной артерии Нижнего Новгорода. Добровольцы собирают мусор вдоль береговой линии, участвуют в экологических играх и слушают лекции о значении реки для экосистемы региона и способах её сохранения. Акция не только делает берега чище, но и привлекает внимание общественности к проблеме загрязнения водоёмов, формируя ответственное отношение к водным ресурсам у подрастающего поколения и всех жителей города.', 'img/ЧистыйБерег.jpg', 'https://admgor.nnov.ru', 1, '2026-04-22 11:13:39'),
(13, 'Семейный экофестиваль «Матушка-Земля»', 'ФЕСТИВАЛИ', '2026-06-05', 'Центр «Экоториум»', '12:00–20:00', 'Бесплатный', 'Праздник заботы о планете для всей семьи.', 'Семейный экофестиваль «Матушка-Земля» — это тёплый и душевный праздник для детей и родителей, посвящённый заботе о природе и экологичному образу жизни. В программе фестиваля: увлекательные игры и квесты на тему экологии, мастер-классы по созданию поделок из вторсырья, а также выставки и интерактивные показы, которые наглядно демонстрируют, как каждый может сделать свою жизнь чуть чище и зеленее. Фестиваль станет отличной возможностью провести выходные с семьёй с пользой, узнать много нового и вдохновить детей на бережное отношение к нашей планете.', 'img/Матушка.jpeg', 'https://niann.ru', 1, '2026-04-22 11:13:39'),
(14, 'Форум «Экология. Технологии. Жизнь 2027»', 'ЛЕКЦИИ', '2027-04-15', 'Нижегородская ярмарка', '09:00–18:00', 'Бесплатный для посетителей, платный для участников (от 500 руб.)', 'Деловой экологический форум.', 'Форум «Экология. Технологии. Жизнь 2027» — это крупнейшая деловая площадка Нижегородской области, посвящённая инновациям в сфере охраны окружающей среды и устойчивому развитию. На форуме будут представлены выставки «зелёных» технологий: от солнечных панелей и энергоэффективного освещения до систем очистки воды и переработки отходов, а также состоятся круглые столы и презентации с участием ведущих экологов, предпринимателей и представителей власти. Мероприятие объединит профессионалов и всех заинтересованных в том, чтобы узнать, как современные технологии помогают сохранить природу, сократить углеродный след и создать комфортную среду для жизни. Посещение выставки — бесплатное, для участия в деловой программе требуется регистрация с символическим взносом.', 'img/ФорумЭкология.png', 'https://ecoforumbvk.ru/', 1, '2026-04-22 11:13:39'),
(15, 'Акция «День без пластика»', 'АКЦИИ', '2026-07-03', 'Торговые центры и парки города', 'Весь день (основные активности 12:00–16:00)', 'Бесплатный', 'День отказа от одноразового пластика.', 'Акция «День без пластика» — это городской эко-челлендж, призванный привлечь внимание к проблеме загрязнения окружающей среды одноразовыми пластиковыми изделиями и популяризировать многоразовые альтернативы. В торговых центрах и парках города волонтёры будут бесплатно раздавать эко-сумки и многоразовые бутылки для воды, а также проводить мастер-классы о том, как легко и просто отказаться от пластика в повседневной жизни. Принять участие в акции может каждый: достаточно выложить в соцсети своё фото с многоразовой кружкой или сумкой с хештегом #ДеньБезПластика и вдохновить друзей на экологичные привычки. Вместе мы можем сократить количество пластикового мусора и сделать наш город чище!', 'img/ПластикНет.jpg', 'https://vk.com/ecocalender', 1, '2026-04-22 11:13:39'),
(16, 'Посадка «Лес Победы» (экологическая часть)', 'АКЦИИ', '2026-05-09', 'Лесопарковые зоны Нижнего Новгорода', '10:00–13:00', 'Бесплатный', 'Экологическая акция памяти.', 'Посадка «Лес Победы» (экологическая часть) — это всероссийская патриотическая акция, в рамках которой в Нижнем Новгороде высаживают деревья в память о героях Великой Отечественной войны. Десятки волонтёров, школьников и семей с детьми выходят в лесопарковые зоны города, чтобы посадить молодые саженцы сосен, берёз и дубов — символы жизни, благодарности и преемственности поколений. Каждое высаженное дерево становится не только вкладом в восстановление зелёных зон и улучшение экологии, но и живым памятником тем, кто защищал нашу Родину. Присоединиться к акции может любой желающий — достаточно взять с собой перчатки и хорошее настроение, чтобы сделать доброе дело для природы и истории.', 'img/ЛесПобеды.jpg', 'https://nn.fpieco.ru', 1, '2026-04-22 11:13:39'),
(17, 'Биеннале экологического искусства (продолжение/вторая волна)', 'КОНКУРСЫ', '2026-04-01', 'Арсенал и другие музеи', 'По расписанию выставок', 'Бесплатный / платный (от 200 руб.)', 'Выставки искусства на тему экологии.', 'Биеннале экологического искусства (продолжение/вторая волна) — это масштабная выставка современного искусства, объединяющая художников из разных стран, которые через творчество осмысляют проблемы окружающей среды, изменения климата и взаимодействия человека с природой. В экспозиции представлены живопись, скульптура, инсталляции из переработанных материалов, видео-арт и перформансы, заставляющие зрителя задуматься о хрупкости экосистем и нашей ответственности перед будущими поколениями. Биеннале проходит на нескольких площадках города — в Арсенале, музеях и галереях, а многие события (лекции, встречи с художниками, дискуссии) доступны для бесплатного посещения. Это уникальная возможность увидеть, как искусство может говорить на языке экологии, вдохновлять на перемены и привлекать внимание к самым острым проблемам планеты.', 'img/Биеналле.jpg', 'https://ecobiennale.ru', 1, '2026-04-22 11:13:39'),
(18, 'Всемирный день водно-болотных угодий', 'АКЦИИ', '2027-02-02', 'Озёра и болотистые зоны области (экскурсии в городе)', '11:00–15:00', 'Бесплатный', 'Просветительская акция о болотах.', 'Всемирный день водно-болотных угодий — это просветительская акция, призванная привлечь внимание к уникальной экосистеме болот, озёр и пойменных лугов, которые играют ключевую роль в очистке воды, поддержании климата и сохранении биоразнообразия. В этот день для всех желающих организуют бесплатные экскурсии на охраняемые природные территории Нижегородской области, лекции орнитологов и мастер-классы по наблюдению за птицами, многие из которых гнездятся именно в водно-болотных угодьях. Участники узнают, почему болота называют «лёгкими планеты», как они спасают от засух и наводнений и почему так важно их охранять. Присоединяйтесь, чтобы открыть для себя удивительный мир природы и научиться беречь то, что нас окружает!', 'img/Болото.jpg', 'https://eco-project.org', 1, '2026-04-22 11:13:39'),
(19, 'Фестиваль «Рок чистой воды»', 'ФЕСТИВАЛИ', '2026-07-27', 'Площадь Минина и Пожарского', '13:00–22:00', 'Бесплатный', 'Музыкальный фестиваль за чистую воду.', 'Фестиваль «Рок чистой воды» — это яркий музыкальный open-air под открытым небом, где драйвовые рок-ритмы соединяются с экологической повесткой и заботой о водных ресурсах планеты. На сцене выступят местные и приглашённые рок-группы, чьи песни посвящены природе, рекам, чистоте и ответственности человека за будущее окружающей среды, а в перерывах между выступлениями гости смогут присоединиться к акции по очистке прилегающей территории. Фестиваль не только дарит заряд энергии и отличное настроение, но и напоминает, что чистая вода — это основа жизни, которую мы обязаны сохранить. Приходите с друзьями, слушайте хорошую музыку и становитесь частью движения за чистоту наших рек и озёр!', 'img/РокВода.jpg', 'https://vk.com/clear_water_rock', 1, '2026-04-22 11:13:39'),
(20, 'Акция «День заповедников»', 'АКЦИИ', '2027-01-11', 'Центр «Экоториум»', '12:00–17:00', 'Бесплатный', 'День особо охраняемых территорий.', 'Акция «День заповедников» — это ежегодное просветительское мероприятие, посвящённое особо охраняемым природным территориям России — заповедникам и национальным паркам, где в первозданном виде сохраняются уникальные ландшафты, редкие виды животных и растений. В центре «Экоториум» гостей ждут увлекательные лекции от учёных-биологов и сотрудников заповедников, а также виртуальные туры с 360-градусным обзором по самым живописным уголкам охраняемой природы — от лесов Керженского заповедника до горных ландшафтов Алтая. Участники узнают, почему заповедники называют «зелёными жемчужинами» страны, какие виды животных удалось спасти от исчезновения благодаря охранному статусу, и как каждый может помочь в сохранении этого природного богатства. Приходите, чтобы открыть для себя удивительный мир дикой природы, который мы обязаны сберечь для будущих поколений!', 'img/Заповедник.jpg', 'https://nn.fpieco.ru', 1, '2026-04-22 11:13:39'),
(21, 'Экологический марафон «Зелёный километр»', 'МЕРОПРИЯТИЯ', '2026-06-08', 'Парк Автозаводский', '09:00–14:00', 'Бесплатный', 'Забег и уборка.', 'Экологический марафон «Зелёный километр» — это необычный спортивно-экологический забег, участники которого не только преодолевают дистанцию, но и собирают мусор по маршруту, совмещая активный отдых с заботой о природе. Маршрут пролегает по живописному Автозаводскому парку, где каждый бегун получает специальный мешок для мусора и перчатки, а на финише всех ждут экологические викторины, призы от организаторов и горячий чай. Марафон показывает, что даже во время пробежки можно сделать доброе дело — собрать пластик, бумагу и стекло, которые отправятся на переработку. Присоединяйтесь к «Зелёному километру», чтобы подарить парку чистоту, а себе — заряд бодрости и хорошего настроения!', 'img/ЗеленМар.jpg', 'https://admgor.nnov.ru', 1, '2026-04-22 11:13:39'),
(22, 'Выставка «Кожа Земли» (экологическое искусство)', 'КОНКУРСЫ', '2027-03-01', 'Волго-Вятский художественный музей', '10:00–18:00', 'Платный (300 руб.)', 'Художественная выставка об экокатастрофах.', 'Выставка «Кожа Земли» (экологическое искусство) — это уникальный художественный проект, в котором современные художники через живопись, скульптуру, инсталляции и мультимедиа исследуют «раны» нашей планеты: вырубку лесов, загрязнение океана, изменение климата и эрозию почв. Многие работы созданы из переработанных материалов — пластиковых бутылок, старой электроники, металлолома и текстильных отходов, что заставляет зрителя задуматься о масштабах потребления и ценности каждой вещи. Выставка располагается в стенах Волго-Вятского художественного музея, а её экспозиция будет интересна как взрослым, так и подросткам, которые через искусство смогут по-новому взглянуть на экологические проблемы и найти вдохновение для личных действий. Не пропустите возможность увидеть, как творчество может говорить на языке экологии, будоражить чувства и пробуждать ответственность за будущее Земли.', 'img/КожаЗемли.jpg', 'https://nn-afisha.ru', 1, '2026-04-22 11:13:39'),
(23, 'Акция «Сохраним птиц» (День зимующих птиц)', 'АКЦИИ', '2027-01-12', 'Скверы и парки города', '10:00–13:00', 'Бесплатный', 'Подкормка и учёт птиц.', 'Акция «Сохраним птиц» (День зимующих птиц) — это добрая зимняя традиция, объединяющая школьников, семьи и всех неравнодушных жителей города в заботе о пернатых, которым трудно пережить холода без человеческой помощи. В парках и скверах Нижнего Новгорода пройдут мастер-классы по изготовлению кормушек из безопасных материалов, а также познавательные занятия, на которых орнитологи расскажут, чем правильно подкармливать синиц, снегирей, воробьёв и других зимующих птиц, а что может им навредить. Участники акции смогут не только смастерить и развесить кормушки, но и принять участие в учёте птиц — увлекательном наблюдении за пернатыми гостями с занесением результатов в общую городскую базу данных. Присоединяйтесь, чтобы помочь птицам пережить зиму и узнать много нового о наших маленьких соседях по планете!', 'img/Птицы.jpg', 'https://vk.com/ecocalender', 1, '2026-04-22 11:13:39'),
(24, 'Городской фестиваль «ЭкоГород 2027»', 'ФЕСТИВАЛИ', '2027-03-20', 'Площадь Горького', '11:00–18:00', 'Бесплатный', 'Фестиваль экологических инициатив.', 'Городской фестиваль «ЭкоГород 2027» — это главная площадка года, где экологические инициативы, инновации и активные горожане встречаются, чтобы вместе обсудить, как сделать Нижний Новгород чище, зеленее и комфортнее для жизни. На площади Горького развернутся выставки лучших экопроектов города: от школьных эко-отрядов и волонтёрских движений до стартапов в области переработки отходов и «зелёной» энергетики. Гостей ждут конкурсы идей и грантов для начинающих эко-активистов, интерактивные зоны для детей, лекции приглашённых экспертов, а также торжественное награждение самых активных участников и организаторов природоохранной деятельности. Приходите всей семьёй, чтобы вдохновиться примерами реальных дел, поделиться своими идеями и стать частью сообщества тех, кто строит экологичное будущее уже сегодня!', 'img/ЭкоГород.jpg', 'https://vk.com/ecogorod_kostroma', 1, '2026-04-22 11:13:39');

