--
-- Структура таблицы `wheel_tasks`
--

CREATE TABLE IF NOT EXISTS `wheel_tasks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `task_short` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int DEFAULT '0',
  `is_active` tinyint DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `wheel_tasks`
--

INSERT INTO `wheel_tasks` (`id`, `task_short`, `task_title`, `task_description`, `task_icon`, `sort_order`, `is_active`, `created_at`) VALUES
(1, 'Задание 1', 'Сортировка мусора', 'Рассортируй домашний мусор: пластик, бумагу, стекло и органику. Сфотографируй результат!', '', 1, 1, '2026-04-17 13:53:28'),
(2, 'Задание 2', 'Экономия воды', 'Принимай душ на 2 минуты меньше обычного. Расскажи семье о важности экономии воды!', '', 2, 1, '2026-04-17 13:53:28'),
(3, 'Задание 3', 'Многоразовая бутылка', 'Используй многоразовую бутылку для воды вместо пластиковой. Поделись фото!', '', 3, 1, '2026-04-17 13:53:28'),
(4, 'Задание 4', 'Сбор батареек', 'Найди ближайший пункт приёма батареек и сдай использованные элементы питания!', '', 4, 1, '2026-04-17 13:53:28'),
(5, 'Задание 5', 'Посади растение', 'Посади цветок или дерево. Ухаживай за ним и наблюдай за ростом!', '', 5, 1, '2026-04-17 13:53:28'),
(6, 'Задание 6', 'Экосумка', 'Сходи в магазин с эко-сумкой вместо пластиковых пакетов. Запиши свои впечатления!', '', 6, 1, '2026-04-17 13:53:28'),
(7, 'Задание 7', 'Экономия энергии', 'Выключай свет и электроприборы, когда они не нужны. Посчитай, сколько сэкономил!', '', 7, 1, '2026-04-17 13:53:28'),
(8, 'Задание 8', 'Уборка территории', 'Прими участие в субботнике или убери мусор в ближайшем парке!', '', 8, 1, '2026-04-17 13:53:28'),
(9, 'Задание 9', 'Поделись знаниями', 'Расскажи друзьям или в соцсетях об экопривычках. Вдохнови других!', '', 9, 1, '2026-04-17 13:53:28'),
(10, 'Задание 10', 'Вторая жизнь вещей', 'Найди старую вещь и преврати её в что-то полезное. Сфотографируй \"до\" и \"после\"!', '', 10, 1, '2026-04-17 13:53:28'),
(11, 'Задание 11', 'Экотранспорт', 'Проедзи на велосипеде или пройдись пешком вместо машины. Посчитай сэкономленный CO2!', '', 11, 1, '2026-04-17 13:53:28'),
(12, 'Задание 12', 'Экокнига', 'Прочитай книгу или статью об экологии. Поделись главным выводом с друзьями!', '', 12, 1, '2026-04-17 13:53:28'),
(13, 'Задание 13', 'День без мяса', 'Организуй один день без мяса. Попробуй вкусные растительные блюда!', '', 13, 1, '2026-04-17 13:53:28'),
(14, 'Задание 14', 'Экокосметика', 'Проверь состав косметики на микропластик. Найди экологичную альтернативу!', '', 14, 1, '2026-04-17 13:53:28'),
(15, 'Задание 15', 'Компостирование', 'Организуй компостную кучу для органических отходов. Начни собирать очистки отдельно!', '', 15, 1, '2026-04-17 13:53:28'),
(16, 'Задание 16', 'Свой пакет', 'Сходи в магазин со своей сумкой, отказавшись от пластикового пакета!', '', 16, 1, '2026-04-17 13:53:28'),
(17, 'Задание 17', 'Помоги природе', 'Покорми птиц зимой или построй кормушку. Поставь поилку для птиц летом!', '', 17, 1, '2026-04-17 13:53:28'),
(18, 'Задание 18', 'Экосубботник', 'Организуй мини-субботник в своем дворе. Пригласи друзей присоединиться!', '', 18, 1, '2026-04-17 13:53:28'),
(19, 'Задание 19', 'Цифровой детокс', 'Проведи день без гаджетов на природе. Погуляй в парке или лесу!', '', 19, 1, '2026-04-17 13:53:28'),
(20, 'Задание 20', 'Экоподарок', 'Сделай подарок из переработанных материалов или подари опыт вместо вещи!', '', 20, 1, '2026-04-17 13:53:28'),
(21, 'Задание 21', 'Береги воду', 'Закрывай кран, когда чистишь зубы. Посчитай, сколько воды сэкономил за день!', '', 21, 1, '2026-04-17 13:53:28'),
(22, 'Задание 22', 'Экосумка своими руками', 'Сшей экосумку из старой футболки или ненужной ткани!', '', 22, 1, '2026-04-17 13:53:28'),
(23, 'Задание 23', 'Многоразовая посуда', 'Откажись от одноразовой посуды. Используй свою кружку для кофе с собой!', '', 23, 1, '2026-04-17 13:53:28'),
(24, 'Задание 24', 'Вырасти зелень', 'Вырасти зелень на подоконнике из семян. Сфотографируй первые всходы!', '', 24, 1, '2026-04-17 13:53:28'),
(25, 'Задание 25', 'Энергосбережение', 'Выключи все приборы из розеток на ночь. Узнай экономию энергии!', '', 25, 1, '2026-04-17 13:53:28'),
(26, 'Задание 26', 'Экочеллендж', 'Брось вызов друзьям: кто больше сдаст батареек/крышечек за неделю?', '', 26, 1, '2026-04-17 13:53:28'),
(27, 'Задание 27', 'Раздельный сбор', 'Организуй дома 4 контейнера для раздельного сбора. Веди статистику месяц!', '', 27, 1, '2026-04-17 13:53:28'),
(28, 'Задание 28', 'Экоподелка', 'Сделай поделку из бросового материала. Придумай ей полезное применение!', '', 28, 1, '2026-04-17 13:53:28'),
(29, 'Задание 29', 'Посади цветы', 'Посади цветы для пчёл и бабочек. Помоги опылителям!', '', 29, 1, '2026-04-17 13:53:28'),
(30, 'Задание 30', 'Экологический дневник', 'Веди дневник экопривычек неделю. Записывай все свои экодела!', '', 30, 1, '2026-04-17 13:53:28');

